// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 time, uint256 amount) public {
        // Bound time to be realistic and amount to be 10 ether exactly
        vm.assume(amount == 10 ether);
        vm.assume(time > c.pastBlockTime() && time < block.timestamp + 100000);
        vm.warp(time);
        vm.deal(address(c), 0);
        // Call fallback function by sending ether with no data
        (bool success, ) = address(c).call{value: amount}("");
        assertTrue(success);
        assertTrue(address(c).balance % 10 ether == 0);
    }
}

